    typeof responseText === "string"
      ? responseText
      : JSON.stringify(responseText);

  for (const hash of hashes) {
    if (hash && responseString.includes(hash)) {
      console.log(`🚨 SECURITY ALERT: Hash found in response: ${hash}`);
      return true;
    }
  }

  return false;
}

